<script>
import WrapContent from "../common/WrapContent.vue";

export default {
  props: {
    contents: {
      type: Array,
    },
  },
  components: {
    WrapContent,
  },
  data() {
    return {
      showFrame: false,
    };
  },
  created() {},
  methods: {
    rangeTextSplit(str) {
      return str.split("@");
    },
    render(route) {
      const url = `${process.env.VUE_APP_SMARTREE_URL}${route}`;
      window.open(url);
    },
    async print() {
      // 이미 iframe이 만들어져 있으면 다시 src만 세팅
      if (!this.showFrame) {
        this.showFrame = true;
      }

      this.$nextTick(() => {
        const iframe = this.$refs.printFrame;
        if (!iframe) return;

        // onload 먼저 걸고 그 다음 src 지정
        iframe.onload = () => {
          if (iframe.contentWindow) {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
          }
        };

        iframe.src = `${window.location.origin}/answerSheet.pdf`;
      });
    },
  },
  watch: {},
};
</script>

